package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TaskRouteTest {@Test void tasksHaveExactOwnerRoutesAndReadOnlyRevisionHistory(){var id="019a0808-1234-7000-8000-000000000001";var root="/api/spaces/"+id+"/tasks";for(var method:new String[]{"GET","POST"})assertEquals("planning",GatewayRoute.select(method,root).service());for(var method:new String[]{"GET","PUT","DELETE"})assertEquals("planning",GatewayRoute.select(method,root+"/"+id).service());assertEquals("planning",GatewayRoute.select("GET",root+"/"+id+"/revisions").service());assertNull(GatewayRoute.select("PUT",root+"/"+id+"/revisions"));assertNull(GatewayRoute.select("POST",root+"/"+id));assertNull(GatewayRoute.select("GET",root+"/"+id+"/share"));assertNull(GatewayRoute.select("POST","/internal/space/planning-authorization"));}}
